window.CARDS=[{"id":"P01","deck":"politik","titleEn":"Campaign Promise","titleId":"Janji Kampanye","en":"Your candidate promised to fix traffic, prices, and jobs in one term. You still half-believe it.","idt":"Calon kamu janji beresin macet, harga, dan lapangan kerja dalam satu periode. Kamu masih setengah percaya.","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"The promise was on a banner. The banner is also a promise."},{"id":"P02","deck":"politik","titleEn":"Budget Increase","titleId":"Kenaikan Anggaran","en":"The road budget rose again. The roads did not.","idt":"Anggaran jalan naik lagi. Jalannya tidak.","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"Budgets go up. Potholes are forever."},{"id":"P03","deck":"politik","titleEn":"Road Project","titleId":"Proyek Jalan","en":"A new road opens. It closes three weeks later for \"maintenance.\"","idt":"Jalan baru dibuka. Tiga minggu kemudian ditutup untuk \"perawatan\".","eff":"Skip 1 turn","e":{"skip":1},"flavor":"Sitting in the detour is part of the project."},{"id":"P04","deck":"politik","titleEn":"Misdirected Subsidy","titleId":"Subsidi Salah Sasaran","en":"The subsidy meant for the poor reached the people who wrote the form. You find the loophole and collect Rp 1,000,000 anyway.","idt":"Subsidi untuk orang miskin nyasar ke yang nulis formulirnya. Kamu nemu celahnya dan tetap dapat Rp 1.000.000.","eff":"Rp +1,000,000","e":{"money":1000000},"flavor":"Systems leak in surprising directions."},{"id":"P05","deck":"politik","titleEn":"Two-Day Bureaucracy","titleId":"Birokrasi Dua Hari","en":"Your permit takes two days. Only if you count the fourteen weeks before it.","idt":"Izinmu butuh dua hari. Itu kalau dihitung empat belas minggu sebelumnya.","eff":"Kewarasan -2","e":{"kew":-2},"flavor":"Two days is the sales pitch."},{"id":"P06","deck":"politik","titleEn":"Lobbying Next Door","titleId":"Lobi Sebelah","en":"A company hires your former manager as its lobbyist. You pay for the lunch that \"clarified\" the policy.","idt":"Perusahaan menyewa mantan atasanmu sebagai pelobi. Kamu bayar makan siang yang \"mengklarifikasi\" kebijakan.","eff":"Rp -2,000,000","e":{"money":-2000000},"flavor":"Revolving doors come with a lunch bill."},{"id":"P07","deck":"politik","titleEn":"Five-Year Election","titleId":"Pemilu Lima Tahunan","en":"Vote, then wait five years to find out what you actually voted for.","idt":"Coblos, lalu tunggu lima tahun untuk tahu apa yang sebenarnya kamu pilih.","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"Democracy is a long-term subscription."},{"id":"P08","deck":"politik","titleEn":"Connected Cousin","titleId":"Sepupu yang Kenal Orang","en":"Your cousin knows someone. You skip the queue.","idt":"Sepupumu kenal orang. Kamu dilangkahi antrean.","eff":"Move to next Institution","e":{"move":"next"},"flavor":"The queue was the system. The cousin is the workaround."},{"id":"P09","deck":"politik","titleEn":"Coordination Meeting","titleId":"Rapat Koordinasi","en":"Eight agencies, three hours, one decision: schedule another meeting.","idt":"Delapan instansi, tiga jam, satu keputusan: jadwalkan rapat lagi.","eff":"Skip 1 turn","e":{"skip":1},"flavor":"Coordination is the product."},{"id":"P10","deck":"politik","titleEn":"Village Fund","titleId":"Dana Desa","en":"Half the village fund goes to the \"socialization\" of the village fund.","idt":"Setengah dana desa habis untuk \"sosialisasi\" dana desa.","eff":"Rp -500,000","e":{"money":-500000},"flavor":"Transparency has a line item too."},{"id":"P11","deck":"politik","titleEn":"Public Service Pledge","titleId":"Janji Pelayanan Publik","en":"\"Fast, transparent, and humble service.\" Please take a number.","idt":"\"Pelayanan cepat, transparan, dan rendah hati.\" Silakan ambil nomor antrean.","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"The number is the only transparent part."},{"id":"P12","deck":"politik","titleEn":"Promise Kept, Sort Of","titleId":"Janji Ditepati, Kira-kira","en":"A promise was kept, in its own way. The fee for keeping it arrives by mail.","idt":"Sebuah janji ditepati, dengan caranya sendiri. Biaya pelaksanaannya datang lewat surat.","eff":"Rp -500,000","e":{"money":-500000},"flavor":"Keeping promises costs extra."},{"id":"P13","deck":"politik","titleEn":"National Debt","titleId":"Utang Negara","en":"You are told the national debt is \"manageable,\" by people who never check their own installments.","idt":"Katanya utang negara masih \"terkendali\", dari orang yang tidak pernah cek cicilannya sendiri.","eff":"Kewarasan -2","e":{"kew":-2},"flavor":"\"Manageable\" is doing a lot of work."},{"id":"P14","deck":"politik","titleEn":"New Tax Policy","titleId":"Kebijakan Pajak Baru","en":"A new tax applies to something you have never bought.","idt":"Ada pajak baru untuk barang yang tidak pernah kamu beli.","eff":"Rp -1,000,000","e":{"money":-1000000},"flavor":"The tax is on the idea of buying."},{"id":"P15","deck":"politik","titleEn":"Public Hearing","titleId":"Dengar Pendapat","en":"You speak for two minutes. Your speech is recorded and then ignored. You still spoke.","idt":"Kamu bicara dua menit. Pidatomu direkam lalu diabaikan. Setidaknya kamu sudah bicara.","eff":"Kewarasan +1","e":{"kew":1},"flavor":"Speaking up is cheap. That is the problem."},{"id":"P16","deck":"politik","titleEn":"Petty Corruption","titleId":"Pungli Kecil","en":"An \"administration fee\" gets your document done faster. There is no receipt, only a feeling.","idt":"\"Biaya administrasi\" bikin dokumenmu cepat selesai. Tidak ada kwitansi, cuma perasaan tidak enak.","eff":"Rp -300,000","e":{"money":-300000},"flavor":"The fee comes with a feeling, not a receipt."},{"id":"P17","deck":"politik","titleEn":"Perspective","titleId":"Soal Sudut Pandang","en":"An official says the numbers are \"a matter of perspective.\" The numbers are in a spreadsheet.","idt":"Pejabat bilang angkanya \"soal sudut pandang\". Angkanya ada di spreadsheet.","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"Perspective is a spreadsheet with the formulas hidden."},{"id":"P18","deck":"politik","titleEn":"Endless Trial","titleId":"Sidang Tak Kunjung Usai","en":"The court case takes so long the defendant becomes a witness.","idt":"Sidangnya begitu lama sampai terdakwanya jadi saksi.","eff":"Skip 1 turn","e":{"skip":1},"flavor":"Justice is slow, and the witness is tired."},{"id":"P19","deck":"politik","titleEn":"Lighthouse Project","titleId":"Proyek Mercusuar","en":"A giant statue is built with the school budget. Everyone takes a photo.","idt":"Patung raksasa dibangun pakai anggaran sekolah. Semua orang foto-foto.","eff":"Rp -2,000,000","e":{"money":-2000000},"flavor":"Photogenic spending."},{"id":"P20","deck":"politik","titleEn":"Donor's Gift","titleId":"Hadiah Donatur","en":"A donor pays for your rally. You will owe them later. You receive Rp 1,000,000 now.","idt":"Donatur membiayai kampanyemu. Kamu akan berutang budi nanti. Kamu terima Rp 1.000.000 sekarang.","eff":"Rp +1,000,000","e":{"money":1000000},"flavor":"Free lunch in politics is a subscription."},{"id":"P21","deck":"politik","titleEn":"Protest Outside the Office","titleId":"Demo di Depan Kantor","en":"Your protest is documented, filed, and forwarded to another office. Shouting feels good for an afternoon.","idt":"Demomu didokumentasikan, diarsipkan, lalu diteruskan ke kantor lain. Teriak itu melegakan, setidaknya untuk sore ini.","eff":"Kewarasan +1","e":{"kew":1},"flavor":"Catharsis is free. Change costs extra."},{"id":"P22","deck":"politik","titleEn":"Self-Censorship","titleId":"Sensor Diri Sendiri","en":"Nobody ordered you to stay quiet. You did it anyway.","idt":"Tidak ada yang menyuruhmu diam. Kamu diam juga.","eff":"Kewarasan -2","e":{"kew":-2},"flavor":"The most efficient censor is the one in your head."},{"id":"P23","deck":"politik","titleEn":"Performance Audit","titleId":"Audit Kinerja","en":"The audit finds \"areas for improvement.\" The areas are everywhere.","idt":"Auditnya menemukan \"area untuk perbaikan\". Areanya ada di mana-mana.","eff":"Rp -500,000","e":{"money":-500000},"flavor":"Audit fees are the only sector that keeps growing."},{"id":"P24","deck":"politik","titleEn":"Election Giveaway","titleId":"Bagi-Bagi Sembako","en":"A free t-shirt and a bag of rice, worth about Rp 300,000. Dignity not included.","idt":"Kaus gratis dan sekarung beras, nilainya sekitar Rp 300.000. Harga diri tidak termasuk.","eff":"Rp +300,000","e":{"money":300000},"flavor":"The rice was always the cheap part."},{"id":"P25","deck":"politik","titleEn":"Food Price Policy","titleId":"Kebijakan Harga Pangan","en":"The government will \"stabilize\" rice prices. Rice has since become a luxury item.","idt":"Pemerintah akan \"menstabilkan\" harga beras. Beras sekarang jadi barang mewah.","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"Stability depends on whose price it is."},{"id":"P26","deck":"politik","titleEn":"New Coordinating Agency","titleId":"Badan Koordinasi Baru","en":"A new agency is formed to coordinate other agencies. It now has its own coordinating agency.","idt":"Dibentuk badan baru untuk mengoordinasikan badan lain. Sekarang badan itu punya badan koordinasinya sendiri.","eff":"Skip 1 turn","e":{"skip":1},"flavor":"Recursion is a job."},{"id":"P27","deck":"politik","titleEn":"Reshuffle","titleId":"Rotasi Jabatan","en":"The official changes seats, not policies. Move to any Institution tile you choose.","idt":"Pejabatnya ganti kursi, bukan kebijakan. Pindah ke Institusi mana pun yang kamu pilih.","eff":"Move to any Institution","e":{"move":"any"},"flavor":"Rotation is the only reform on schedule."},{"id":"P28","deck":"politik","titleEn":"Public Opinion Poll","titleId":"Survei Opini Publik","en":"A poll says 62 percent are unhappy. The poll itself is also unhappy.","idt":"Survei bilang 62 persen tidak puas. Surveinya juga tidak puas.","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"Even the data is tired."},{"id":"P29","deck":"politik","titleEn":"Independent Oversight","titleId":"Pengawasan Independen","en":"An oversight body reviews the oversight body. It fines someone else. You receive Rp 500,000.","idt":"Badan pengawas memeriksa badan pengawas. Denda dikenakan ke orang lain. Kamu terima Rp 500.000.","eff":"Rp +500,000","e":{"money":500000},"flavor":"Oversight is the one thing that gets outsourced."},{"id":"P30","deck":"politik","titleEn":"Reform Meeting Cancelled","titleId":"Rapat Reformasi Dibatalkan","en":"The system reform meeting is cancelled. You feel a small, slightly shameful relief.","idt":"Rapat reformasi sistem dibatalkan. Kamu merasa lega, sedikit memalukan.","eff":"Kewarasan +1","e":{"kew":1},"flavor":"Some reform is simply postponed indefinitely."},{"id":"U01","deck":"ugly","titleEn":"Raise, Then Prices","titleId":"Gaji Naik, Harga Naik","en":"Your salary rose 5 percent. Your rent rose 12 percent.","idt":"Gajimu naik 5 persen. Sewa kosmu naik 12 persen.","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"Math is the one subject nobody here passed."},{"id":"U02","deck":"ugly","titleEn":"Retirement Is a Myth","titleId":"Pensiun Itu Mitos","en":"You will work until you die, under a slightly different job title.","idt":"Kamu akan kerja sampai mati, dengan jabatan yang sedikit berbeda.","eff":"Kewarasan -2","e":{"kew":-2},"flavor":"Job titles are the only thing that gets promoted."},{"id":"U03","deck":"ugly","titleEn":"Getting Older","titleId":"Makin Tua","en":"Nobody tells you the age when you are \"expected to know things.\" You are there now.","idt":"Tidak ada yang bilang kapan kamu \"diharapkan sudah tahu segalanya\". Kamu sudah di situ.","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"Adulthood arrives without a manual."},{"id":"U04","deck":"ugly","titleEn":"Permanent Contract","titleId":"Kontrak Tetap","en":"Your contract is \"permanent.\" It expires in three months.","idt":"Kontrakmu \"tetap\". Masa berlakunya tiga bulan.","eff":"Kewarasan -2","e":{"kew":-2},"flavor":"Permanent is a word, not a promise."},{"id":"U05","deck":"ugly","titleEn":"Paid on the Second","titleId":"Gajian Tanggal Dua","en":"Your salary arrived on the 28th and left on the 1st.","idt":"Gajimu masuk tanggal 28 dan keluar tanggal 1.","eff":"Rp -1,000,000","e":{"money":-1000000},"flavor":"Payday is a rumor you hear about from friends."},{"id":"U06","deck":"ugly","titleEn":"Bonus","titleId":"Bonus","en":"You get a bonus of Rp 800,000. Your phone bill just rose by Rp 800,000.","idt":"Dapat bonus Rp 800.000. Tagihan HP naik Rp 800.000.","eff":"Rp +800,000","e":{"money":800000},"flavor":"The bonus was spent before it arrived."},{"id":"U07","deck":"ugly","titleEn":"Dream House","titleId":"Rumah Impian","en":"The house is affordable, if you live forty years and never get sick.","idt":"Rumahnya terjangkau, asal kamu hidup empat puluh tahun dan tidak pernah sakit.","eff":"Kewarasan -2","e":{"kew":-2},"flavor":"\"Affordable\" is a condition, not a price."},{"id":"U08","deck":"ugly","titleEn":"Work From Home","titleId":"Kerja dari Rumah","en":"Work from home means working from the bed, the kitchen, and the car.","idt":"Kerja dari rumah artinya kerja dari kasur, dapur, dan mobil.","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"The office followed you home and didn't bring the snacks."},{"id":"U09","deck":"ugly","titleEn":"Health Is Expensive","titleId":"Sehat Itu Mahal","en":"Your insurance covers everything except the thing you have.","idt":"Asuransimu menanggung semua kecuali penyakit yang kamu punya.","eff":"Rp -1,500,000","e":{"money":-1500000},"flavor":"Coverage is a list with an exclusion attached."},{"id":"U10","deck":"ugly","titleEn":"Degree Required","titleId":"Gelar Wajib","en":"Your degree is required for jobs that pay less than the degree cost you.","idt":"Gelarmu diwajibkan untuk pekerjaan yang gajinya lebih kecil dari biaya kuliahmu.","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"The return on education is not on the balance sheet."},{"id":"U11","deck":"ugly","titleEn":"Nothing Is Free","titleId":"Tidak Ada yang Gratis","en":"The app is free. You are the product, and also the payment.","idt":"Aplikasinya gratis. Kamu produknya, sekaligus pembayarnya.","eff":"Rp -300,000","e":{"money":-300000},"flavor":"The price was hidden in the terms and conditions."},{"id":"U12","deck":"ugly","titleEn":"Emergency Fund","titleId":"Dana Darurat","en":"Your emergency fund is now your emergency.","idt":"Dana daruratmu sekarang jadi keadaan daruratmu.","eff":"Rp -2,000,000","e":{"money":-2000000},"flavor":"Savings are only savings until a Tuesday."},{"id":"U13","deck":"ugly","titleEn":"College Friends","titleId":"Teman Kuliah","en":"Your college friends are now all LinkedIn posts.","idt":"Teman kuliahmu sekarang semuanya isi postingan LinkedIn.","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"Everyone is \"excited to announce\" something."},{"id":"U14","deck":"ugly","titleEn":"The Rich Get Richer","titleId":"Yang Kaya Makin Kaya","en":"Compound interest works for people who already have capital. You are watching.","idt":"Bunga majemuk bekerja untuk yang sudah punya modal. Kamu cuma menonton.","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"Compounding is a spectator sport."},{"id":"U15","deck":"ugly","titleEn":"Holiday Cost","titleId":"Biaya Liburan","en":"You took a holiday. The holiday took your savings.","idt":"Kamu liburan. Liburannya mengambil tabunganmu.","eff":"Rp -1,200,000","e":{"money":-1200000},"flavor":"The one time you save and spend at once."},{"id":"U16","deck":"ugly","titleEn":"Age Thirty","titleId":"Umur Tiga Puluh","en":"At thirty you are too old for entry-level and too young for respect.","idt":"Di umur tiga puluh kamu terlalu tua untuk level pemula dan terlalu muda untuk dihormati.","eff":"Kewarasan -2","e":{"kew":-2},"flavor":"The middle is the most crowded part of life."},{"id":"U17","deck":"ugly","titleEn":"Hard Work Isn't Enough","titleId":"Kerja Keras Saja Tidak Cukup","en":"Hard work is the answer. It is just not the answer to the question you asked.","idt":"Kerja keras adalah jawabannya. Sayangnya bukan jawaban untuk pertanyaanmu.","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"Effort is not a strategy, but it is a symptom."},{"id":"U18","deck":"ugly","titleEn":"Tax on Everything","titleId":"Pajak untuk Semuanya","en":"You pay tax on your salary, then on your savings, then on your coffee.","idt":"Kamu bayar pajak dari gaji, dari tabungan, lalu dari kopimu.","eff":"Rp -1,000,000","e":{"money":-1000000},"flavor":"The coffee is taxed once as coffee and once as luxury."},{"id":"U19","deck":"ugly","titleEn":"Paid by the Project","titleId":"Dibayar per Proyek","en":"You are paid per project. The project never ends.","idt":"Kamu dibayar per proyek. Proyeknya tidak pernah selesai.","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"Freelancing is a permanent deadline."},{"id":"U20","deck":"ugly","titleEn":"Needs vs Wants","titleId":"Kebutuhan vs Keinginan","en":"Your \"wants\" list now includes oxygen and parking.","idt":"Daftar \"keinginan\"-mu sekarang mencakup oksigen dan parkir.","eff":"Rp -600,000","e":{"money":-600000},"flavor":"Nothing is optional when everything is a subscription."},{"id":"U21","deck":"ugly","titleEn":"Parents Are Proud","titleId":"Orang Tua Bangga","en":"Your parents are proud of your job title. They do not know your salary.","idt":"Orang tuamu bangga dengan jabatanmu. Mereka tidak tahu gajimu.","eff":"Kewarasan +1","e":{"kew":1},"flavor":"A small victory is still a victory."},{"id":"U22","deck":"ugly","titleEn":"Motorbike Installment","titleId":"Cicilan Motor","en":"Your motorbike will be paid off in 2029. So will your back.","idt":"Motormu lunas tahun 2029. Punggungmu juga.","eff":"Rp -500,000","e":{"money":-500000},"flavor":"Installments outlast the warranty."},{"id":"U23","deck":"ugly","titleEn":"Real Life","titleId":"Hidup Nyata","en":"Real life has no skip button, no reset, and no Kewarasan meter.","idt":"Hidup nyata tidak punya tombol skip, reset, atau meter Kewarasan.","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"You are no longer in the tutorial."},{"id":"U24","deck":"ugly","titleEn":"Nobody Taught You","titleId":"Tidak Ada yang Mengajarimu","en":"Nobody taught you taxes, contracts, or how to say no. You pay Rp 500,000 for a course.","idt":"Tidak ada yang mengajarimu pajak, kontrak, atau cara bilang tidak. Kamu bayar Rp 500.000 untuk kursusnya.","eff":"Rp -500,000","e":{"money":-500000},"flavor":"The course is the first thing you can afford to learn."},{"id":"U25","deck":"ugly","titleEn":"More Money, Less Everything","titleId":"Uang Naik, Yang Lain Turun","en":"You have more money than last year and less of everything else.","idt":"Uangmu lebih banyak dari tahun lalu. Sisanya lebih sedikit.","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"The spreadsheet is up. The soul is down."},{"id":"D01","deck":"dark","titleEn":"Expensive Funeral","titleId":"Pemakaman Mahal","en":"Even dying now requires a payment plan.","idt":"Bahkan mati sekarang butuh cicilan.","eff":"Rp -1,500,000","e":{"money":-1500000},"flavor":"The final bill arrives after the final breath."},{"id":"D02","deck":"dark","titleEn":"Fine Print","titleId":"Tulisan Kecil","en":"Your life insurance has forty-seven exclusions. Yours is \"lifestyle.\"","idt":"Asuransi jiwamu punya empat puluh tujuh pengecualian. Punyamu: \"gaya hidup.\"","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"Lifestyle is a pre-existing condition."},{"id":"D03","deck":"dark","titleEn":"Doomsday Scheduled","titleId":"Kiamat Dijadwalkan","en":"The world may end on Thursday. Your credit card does not care.","idt":"Dunia mungkin kiamat hari Kamis. Kartu kreditmu tidak peduli.","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"Late fees survive the apocalypse."},{"id":"D04","deck":"dark","titleEn":"Installments, Not Debt","titleId":"Cicilan, Bukan Utang","en":"You are not in debt. You are in installments, which is different, legally.","idt":"Kamu tidak punya utang. Kamu punya cicilan. Secara hukum itu beda.","eff":"Kewarasan -2","e":{"kew":-2},"flavor":"Semantics are a financial product."},{"id":"D05","deck":"dark","titleEn":"Dr. Google","titleId":"Dokter Google","en":"You searched your symptoms. The algorithm diagnosed terminal boredom.","idt":"Kamu cari gejalamu di internet. Algoritmanya mendiagnosis bosan stadium akhir.","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"The only confident diagnosis you will get all week."},{"id":"D06","deck":"dark","titleEn":"Slow Career Death","titleId":"Karier yang Mati Pelan-Pelan","en":"Your career is dying slowly, but HR says it is \"in a growth phase.\"","idt":"Kariermu mati pelan-pelan, tapi HR bilang sedang \"fase bertumbuh\".","eff":"Kewarasan -2","e":{"kew":-2},"flavor":"Growth is the word they use for everything."},{"id":"D07","deck":"dark","titleEn":"Last Will","titleId":"Surat Wasiat","en":"Your will has one asset: an e-wallet balance. It has one liability: everything else.","idt":"Surat wasiatmu punya satu aset: saldo e-wallet. Satu kewajiban: semuanya yang lain.","eff":"Rp -200,000","e":{"money":-200000},"flavor":"Estate planning for people with no estate."},{"id":"D08","deck":"dark","titleEn":"Gravesite Installments","titleId":"Cicilan Makam","en":"You can now pay for your grave in thirty-six easy installments, with no down payment.","idt":"Sekarang kamu bisa cicil makam tiga puluh enam kali, tanpa DP.","eff":"Rp -800,000","e":{"money":-800000},"flavor":"Easy payments all the way down."},{"id":"D09","deck":"dark","titleEn":"Funeral Reflection","titleId":"Refleksi di Pemakaman","en":"At your uncle's funeral, your boss says, \"This is a time for reflection.\"","idt":"Di pemakaman pamanmu, bosmu bilang, \"Ini waktunya refleksi.\"","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"Reflection, billed to the team."},{"id":"D10","deck":"dark","titleEn":"Robot Replacement","titleId":"Robot Pengganti","en":"Your job was automated. The robot is paid less and never cries in meetings.","idt":"Pekerjaanmu diotomatisasi. Robotnya dibayar lebih sedikit dan tidak pernah menangis di rapat.","eff":"Kewarasan -2","e":{"kew":-2},"flavor":"The robot is cheaper and better at pretending."},{"id":"D11","deck":"dark","titleEn":"Retire After Dying","titleId":"Pensiun Setelah Mati","en":"You will retire the day after you can afford to. The date keeps moving forward.","idt":"Kamu akan pensiun sehari setelah mampu. Tanggalnya terus maju.","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"Retirement is a calendar with a missing month."},{"id":"D12","deck":"dark","titleEn":"Debt Collector's Contacts","titleId":"Kontak Penagih","en":"The debt collector has your contacts list. Your mother now gets a payment reminder too.","idt":"Penagih utang punya daftar kontakmu. Ibumu sekarang ikut dapat pengingat bayar.","eff":"Kewarasan -2","e":{"kew":-2},"flavor":"Predatory lending has a very long address book."},{"id":"D13","deck":"dark","titleEn":"Happiness Course","titleId":"Kursus Bahagia","en":"A happiness course costs Rp 2,000,000. You leave more anxious, with a certificate.","idt":"Kursus bahagia harganya Rp 2.000.000. Kamu pulang lebih cemas, dengan sertifikat.","eff":"Rp -2,000,000","e":{"money":-2000000},"flavor":"The certificate is the only thing that looks happy."},{"id":"D14","deck":"dark","titleEn":"Inherited Mess","titleId":"Warisan Berantakan","en":"Your child will inherit a planet, a mortgage, and your group chat.","idt":"Anakmu akan mewarisi planet, KPR, dan grup chatmu.","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"The group chat is the only asset that appreciates."},{"id":"D15","deck":"dark","titleEn":"Power Outage","titleId":"Listrik Padam","en":"The power went out during your video call. The outage was the most productive thing all week.","idt":"Listrik padam saat video call. Padamnya itu hal paling produktif minggu ini.","eff":"Skip 1 turn","e":{"skip":1},"flavor":"Blackouts have the best attendance record."},{"id":"D16","deck":"dark","titleEn":"Last Message","titleId":"Pesan Terakhir","en":"You wrote \"good night\" to the bank app. It replied with a promo.","idt":"Kamu mengetik \"selamat malam\" ke aplikasi bank. Dibalas dengan promo.","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"Even the goodbye has a sponsor."},{"id":"D17","deck":"dark","titleEn":"Tax Apocalypse","titleId":"Kiamat Pajak","en":"Your tax consultant files for relief. You pay the full amount.","idt":"Konsultan pajakmu sendiri minta keringanan. Kamu bayar penuh.","eff":"Rp -1,500,000","e":{"money":-1500000},"flavor":"When the professional gives up, you pay full price."},{"id":"D18","deck":"dark","titleEn":"Average Life Expectancy","titleId":"Harapan Hidup Rata-Rata","en":"Life expectancy is long enough to pay off your debt. Just barely.","idt":"Harapan hidup cukup panjang untuk melunasi utangmu. Pas-pasan.","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"\"Just barely\" is the national motto."},{"id":"D19","deck":"dark","titleEn":"Coffee Budget","titleId":"Anggaran Kopi","en":"Your coffee machine costs more than your emergency fund.","idt":"Mesin kopimu lebih mahal dari dana daruratmu.","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"The espresso is doing better than you."},{"id":"D20","deck":"dark","titleEn":"Killing Time","titleId":"Membunuh Waktu","en":"You spent three hours scrolling. Time was wasted, and so were you.","idt":"Kamu scroll selama tiga jam. Waktu terbuang, dan kamu juga.","eff":"Kewarasan -2","e":{"kew":-2},"flavor":"Time is the one thing that can't be refunded."},{"id":"D21","deck":"dark","titleEn":"Immortal Credit Card","titleId":"Kartu Kredit Abadi","en":"Your credit card will outlive you. You pay Rp 1,000,000 in annual fees.","idt":"Kartu kreditmu akan lebih awet dari kamu. Kamu bayar Rp 1.000.000 iuran tahunan.","eff":"Rp -1,000,000","e":{"money":-1000000},"flavor":"The annual fee lasts as long as the card does."},{"id":"D22","deck":"dark","titleEn":"Startup Shutdown","titleId":"Startup Tutup","en":"Your startup shut down. The pitch deck survives, in a folder called \"Learnings.\"","idt":"Startupmu tutup. Pitch deck-nya selamat, di folder bernama \"Pelajaran.\"","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"Learnings are the only thing scaling."},{"id":"D23","deck":"dark","titleEn":"Totaled Car","titleId":"Mobil Total Loss","en":"The car is totaled. So is your plan for the year.","idt":"Mobilnya total loss. Rencanamu setahun ini juga.","eff":"Rp -2,000,000","e":{"money":-2000000},"flavor":"\"Total loss\" describes most annual plans."},{"id":"D24","deck":"dark","titleEn":"Digital Junk","titleId":"Sampah Digital","en":"Your phone storage is full of memes you never read.","idt":"Penyimpanan HP-mu penuh meme yang tidak pernah kamu baca.","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"The archive is bigger than your life."},{"id":"D25","deck":"dark","titleEn":"Dream of Being Rich","titleId":"Mimpi Jadi Kaya","en":"You dreamed you were rich. You woke up to a payment reminder.","idt":"Kamu mimpi jadi orang kaya. Bangun-bangun ada pengingat bayar.","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"The dream had a sponsor."},{"id":"S01","deck":"sarcasm","titleEn":"We Are Progressing","titleId":"Kita Sudah Maju","en":"The city has a new café. The old café is now a bank.","idt":"Kota punya kafe baru. Kafe yang lama sekarang jadi bank.","eff":"Kewarasan +1","e":{"kew":1},"flavor":"Progress is measured in lattes."},{"id":"S02","deck":"sarcasm","titleEn":"That Is Normal","titleId":"Itu Normal","en":"Your manager says \"this is normal\" for the third time today.","idt":"Manajermu bilang \"ini normal\" untuk ketiga kalinya hari ini.","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"\"Normal\" is a word that needs a raise."},{"id":"S03","deck":"sarcasm","titleEn":"Economic Growth","titleId":"Pertumbuhan Ekonomi","en":"GDP grew. Your savings did not. Both can be true.","idt":"PDB tumbuh. Tabunganmu tidak. Keduanya bisa benar.","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"Statistics are rarely about the person holding the statistics."},{"id":"S04","deck":"sarcasm","titleEn":"Results Matter","titleId":"Hasil Itu Penting","en":"Your results are reviewed in a meeting about the review.","idt":"Hasil kerjamu dibahas di rapat tentang evaluasi.","eff":"Skip 1 turn","e":{"skip":1},"flavor":"The review has a review."},{"id":"S05","deck":"sarcasm","titleEn":"Employee Appreciation","titleId":"Apresiasi Karyawan","en":"You get a certificate of appreciation, printed on the back of a budget form.","idt":"Kamu dapat sertifikat apresiasi, dicetak di belakang formulir anggaran.","eff":"Kewarasan +1","e":{"kew":1},"flavor":"Appreciation is cheap. The paper is recycled."},{"id":"S06","deck":"sarcasm","titleEn":"Work-Life Balance","titleId":"Keseimbangan Hidup-Kerja","en":"Your work-life balance is a tab you never click.","idt":"Keseimbangan hidup-kerjamu itu tab yang tidak pernah kamu klik.","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"It sits in the settings menu, under \"Coming Soon.\""},{"id":"S07","deck":"sarcasm","titleEn":"App Updated","titleId":"Aplikasi Diperbarui","en":"Your banking app updated. Now you cannot log in. At least you are free.","idt":"Aplikasi bank diperbarui. Sekarang tidak bisa login. Setidaknya kamu bebas.","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"Freedom came with an error message."},{"id":"S08","deck":"sarcasm","titleEn":"Expensive Coffee","titleId":"Kopi Mahal","en":"A coffee costs Rp 50,000. You are paying for the Wi-Fi password.","idt":"Segelas kopi Rp 50.000. Kamu bayar sandi Wi-Fi-nya.","eff":"Rp -50,000","e":{"money":-50000},"flavor":"The Wi-Fi password is the real product."},{"id":"S09","deck":"sarcasm","titleEn":"Saved by Skipping","titleId":"Hemat dengan Melewatkan","en":"You saved money by skipping the coffee. The café noticed.","idt":"Kamu hemat dengan tidak beli kopi. Kafenya sadar.","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"Loyalty programs track absence too."},{"id":"S10","deck":"sarcasm","titleEn":"Moving Forward Together","titleId":"Maju Bersama","en":"The group chat is moving forward together, toward the same unsolved problem.","idt":"Grup chat maju bersama menuju masalah yang sama yang belum selesai.","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"Teamwork is a shared spreadsheet with no owner."},{"id":"S11","deck":"sarcasm","titleEn":"Empowering the Team","titleId":"Memberdayakan Tim","en":"Your leader empowers the team by giving it more tasks.","idt":"Pemimpinmu memberdayakan tim dengan menambah tugas.","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"Empowerment is delegation with a nicer font."},{"id":"S12","deck":"sarcasm","titleEn":"Good News on Rent","titleId":"Kabar Baik soal Sewa","en":"Good news: your rent is frozen at a forty percent increase.","idt":"Kabar baik: sewamu dibekukan di kenaikan empat puluh persen.","eff":"Rp -800,000","e":{"money":-800000},"flavor":"\"Frozen\" means it stopped at a painful level."},{"id":"S13","deck":"sarcasm","titleEn":"Morning Motivation","titleId":"Motivasi Pagi","en":"Your morning motivation quote was about hustle. You read it at 3 a.m., unable to sleep.","idt":"Kutipan motivasi paginya tentang hustle. Kamu membacanya jam tiga pagi, sambil tidak bisa tidur.","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"Inspiration at 3 a.m. is a symptom."},{"id":"S14","deck":"sarcasm","titleEn":"Worth It","titleId":"Sepadan","en":"Your new phone was \"worth it.\" Now you are the one who feels not worth it.","idt":"HP barumu \"sepadan\". Sekarang kamu yang merasa tidak sepadan.","eff":"Rp -3,000,000","e":{"money":-3000000},"flavor":"Upgrades are the only thing that goes up when you do."},{"id":"S15","deck":"sarcasm","titleEn":"They Were Right","titleId":"Mereka Benar","en":"Your uncle says \"just save money.\" He is right, and you still lose Kewarasan.","idt":"Pamanmu bilang \"tabung saja\". Dia benar, dan kamu tetap kehilangan kewarasan.","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"Advice is free, and so is the sting."},{"id":"S16","deck":"sarcasm","titleEn":"Limited-Time Offer","titleId":"Penawaran Terbatas","en":"The sale ends in ten minutes. It has been ending in ten minutes since 2019.","idt":"Diskonnya habis dalam sepuluh menit. Sudah \"habis dalam sepuluh menit\" sejak 2019.","eff":"Rp -1,000,000","e":{"money":-1000000},"flavor":"Scarcity is a marketing budget."},{"id":"S17","deck":"sarcasm","titleEn":"Busy Is a Personality","titleId":"Sibuk Itu Kepribadian","en":"You are busy. Busy is now your personality.","idt":"Kamu sibuk. Sibuk sekarang jadi kepribadianmu.","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"Ask someone how they are, and they show you their calendar."},{"id":"S18","deck":"sarcasm","titleEn":"Productive Day","titleId":"Hari yang Produktif","en":"You opened fourteen tabs and closed none. You are very productive.","idt":"Kamu buka empat belas tab dan tidak menutup satu pun. Kamu produktif sekali.","eff":"Kewarasan +1","e":{"kew":1},"flavor":"Tabs are the only thing you complete."},{"id":"S19","deck":"sarcasm","titleEn":"Thanks for the Feedback","titleId":"Terima Kasih Masukannya","en":"Your feedback has been \"noted.\" Noted, filed, and archived.","idt":"Masukanmu sudah \"dicatat\". Dicatat, diarsipkan, selesai.","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"\"Noted\" is the most polite form of ignored."},{"id":"S20","deck":"sarcasm","titleEn":"Our Version of Success","titleId":"Versi Sukses Kita","en":"Success is defined by the quarterly report. Your quarter was bad.","idt":"Sukses didefinisikan oleh laporan kuartalan. Kuartalmu buruk.","eff":"Kewarasan -2","e":{"kew":-2},"flavor":"The quarterly report has no column for sleep."},{"id":"H01","deck":"modern","titleEn":"Doomscrolling","titleId":"Doomscrolling","en":"You opened the app for one minute. It is now 2 a.m.","idt":"Kamu buka aplikasi cuma satu menit. Sekarang jam 2 pagi.","eff":"Kewarasan -2","e":{"kew":-2},"flavor":"One minute is an industry measurement."},{"id":"H02","deck":"modern","titleEn":"Family Group Chat","titleId":"Grup Keluarga","en":"The family group forwarded a health claim. You have no time to read it. Everyone in the chat is a doctor.","idt":"Grup keluarga meneruskan klaim kesehatan. Kamu tidak punya waktu membacanya. Di grup itu, semua orang jadi dokter.","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"Everyone is a doctor in the group chat."},{"id":"H03","deck":"modern","titleEn":"Night Notification","titleId":"Notifikasi Malam","en":"A message arrives at 11 p.m.: \"quick question.\"","idt":"Ada pesan jam 11 malam: \"pertanyaan singkat\".","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"Quick questions have no end time."},{"id":"H04","deck":"modern","titleEn":"New KPI","titleId":"KPI Baru","en":"Your KPI now includes \"passion.\" It cannot be measured.","idt":"KPI-mu sekarang ditambah \"passion\". Tidak bisa diukur.","eff":"Kewarasan -2","e":{"kew":-2},"flavor":"Passion is measured in overtime."},{"id":"H05","deck":"modern","titleEn":"The Algorithm Knows","titleId":"Algoritma Tahu","en":"The algorithm showed a loan ad right after you typed \"so tired.\"","idt":"Algoritma menampilkan iklan pinjaman tepat setelah kamu mengetik \"capek banget\".","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"Your feelings were the targeting data."},{"id":"H06","deck":"modern","titleEn":"Gig Earnings","titleId":"Penghasilan Gig","en":"You earned Rp 180,000 after the platform took its cut.","idt":"Kamu dapat Rp 180.000 setelah potongan platform.","eff":"Rp +180,000","e":{"money":180000},"flavor":"The platform's cut is larger than your fuel."},{"id":"H07","deck":"modern","titleEn":"Traffic Again","titleId":"Macet Lagi","en":"Highway traffic. The car ahead is not moving either, philosophically.","idt":"Macet di tol. Mobil di depanmu juga tidak bergerak, secara filosofis.","eff":"Skip 1 turn","e":{"skip":1},"flavor":"Traffic is a long meditation nobody signed up for."},{"id":"H08","deck":"modern","titleEn":"Side Hustle","titleId":"Bisnis Sampingan","en":"You started a side hustle selling candles. The molds cost more than the candles.","idt":"Kamu mulai bisnis lilin. Cetakannya lebih mahal dari lilinnya.","eff":"Rp -300,000","e":{"money":-300000},"flavor":"Every side hustle starts with a main expense."},{"id":"H09","deck":"modern","titleEn":"Expensive Hangout","titleId":"Nongkrong Mahal","en":"Your friend's birthday at a café costs Rp 350,000. You came for the friend.","idt":"Ulang tahun temanmu di kafe: Rp 350.000. Kamu datang untuk temanmu.","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"Friendship has a cover charge."},{"id":"H10","deck":"modern","titleEn":"Self-Care: Afternoon Nap","titleId":"Self-Care: Tidur Siang","en":"You take a twenty-minute nap. The ceiling fan is your therapist.","idt":"Kamu tidur siang dua puluh menit. Kipas angin jadi terapismu.","eff":"Kewarasan +1","e":{"kew":1},"flavor":"Quick rest, zero cost.","selfCare":true},{"id":"H11","deck":"modern","titleEn":"Self-Care: Walk Without Phone","titleId":"Self-Care: Jalan Tanpa HP","en":"You walk around the block and leave the phone at home.","idt":"Kamu jalan keliling blok dan HP-nya tertinggal di rumah.","eff":"Kewarasan +2","e":{"kew":2},"flavor":"Fresh air, no notifications, one good decision.","selfCare":true},{"id":"H12","deck":"modern","titleEn":"Self-Care: Home Cooking","titleId":"Self-Care: Masak di Rumah","en":"You cook a dinner that did not come in a box.","idt":"Kamu masak makan malam yang tidak datang dari kotak.","eff":"Kewarasan +1","e":{"kew":1},"flavor":"The pan was the real therapist.","selfCare":true},{"id":"H13","deck":"modern","titleEn":"Self-Care: Mute Notifications","titleId":"Self-Care: Matikan Notifikasi","en":"You mute every app. Nothing important was missed. Probably.","idt":"Kamu matikan semua notifikasi. Tidak ada yang penting terlewat. Mungkin.","eff":"Kewarasan +2","e":{"kew":2},"flavor":"Probably is the most honest word here.","selfCare":true},{"id":"H14","deck":"modern","titleEn":"Self-Care: Call a Friend","titleId":"Self-Care: Telepon Teman","en":"You call a friend and talk for ten minutes about nothing important.","idt":"Kamu telepon teman dan ngobrol sepuluh menit tentang hal yang tidak penting.","eff":"Kewarasan +2","e":{"kew":2},"flavor":"Nothing is the best thing to talk about.","selfCare":true},{"id":"H15","deck":"modern","titleEn":"Quick Call","titleId":"Panggilan Singkat","en":"You are asked to \"hop on a quick call.\" It is not quick.","idt":"Kamu diminta \"ikut panggilan singkat\". Ternyata tidak singkat.","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"\"Quick\" is a time zone."},{"id":"H16","deck":"modern","titleEn":"Monday","titleId":"Senin","en":"Monday arrived early this week. It is Thursday.","idt":"Senin datang lebih awal minggu ini. Hari ini Kamis.","eff":"Skip 1 turn","e":{"skip":1},"flavor":"Monday is a mood, not a day."},{"id":"H17","deck":"modern","titleEn":"Holiday Posts","titleId":"Postingan Liburan","en":"Everyone's holiday looks perfect. Yours looks like a photo of luggage.","idt":"Liburan semua orang kelihatan sempurna. Liburanmu cuma foto koper.","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"The photo of luggage is the most honest post."},{"id":"H18","deck":"modern","titleEn":"Balance Check","titleId":"Cek Saldo","en":"You check your balance, then close the app. The number is still there.","idt":"Kamu cek saldo, lalu tutup aplikasinya. Angkanya masih di sana.","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"The number waits patiently."},{"id":"H19","deck":"modern","titleEn":"Culture Livestream","titleId":"Livestream Budaya Kerja","en":"Your company wants you to livestream the company culture.","idt":"Perusahaanmu minta kamu livestream budaya kerja.","eff":"Kewarasan -2","e":{"kew":-2},"flavor":"Culture is now a content calendar."},{"id":"H20","deck":"modern","titleEn":"Office Coffee Machine","titleId":"Mesin Kopi Kantor","en":"The office coffee machine is broken, like the meeting schedule.","idt":"Mesin kopi kantor rusak, sama seperti jadwal rapatnya.","eff":"Skip 1 turn","e":{"skip":1},"flavor":"Everything runs on a plan that has stopped."},{"id":"H21","deck":"modern","titleEn":"Unread Messages","titleId":"Pesan Belum Dibaca","en":"You have 412 unread messages. Somehow the number is your fault.","idt":"Ada 412 pesan belum dibaca. Entah kenapa itu salahmu.","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"The inbox is a guilt tracker."},{"id":"H22","deck":"modern","titleEn":"City Move","titleId":"Pindah Kota","en":"You moved to the city for a better life. The city moved you to a smaller room.","idt":"Kamu pindah ke kota demi hidup yang lebih baik. Kota memindahkanmu ke kamar yang lebih kecil.","eff":"Rp -1,500,000","e":{"money":-1500000},"flavor":"Upward mobility, with a smaller room."},{"id":"H23","deck":"modern","titleEn":"No Free Time","titleId":"Tidak Ada Waktu Luang","en":"You planned your free time. The plan took all of it.","idt":"Kamu merencanakan waktu luangmu. Rencananya memakan semuanya.","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"Scheduling was the leisure."},{"id":"H24","deck":"modern","titleEn":"Self-Care: Houseplant","titleId":"Self-Care: Tanaman Hias","en":"You bought a plant and did not kill it. Yet.","idt":"Kamu beli tanaman dan belum membunuhnya. Belum.","eff":"Kewarasan +1","e":{"kew":1},"flavor":"Keep it alive, as an achievement.","selfCare":true},{"id":"H25","deck":"modern","titleEn":"Settled Life","titleId":"Hidup Mapan","en":"Your coworker bought a house. Your coworker is twenty-five.","idt":"Rekanmu beli rumah. Umur rekanmu dua puluh lima.","eff":"Kewarasan -2","e":{"kew":-2},"flavor":"Some people started at a different starting line."},{"id":"K01","deck":"finance","titleEn":"Inflation","titleId":"Inflasi","en":"Prices rose 4 percent. Your savings rose 0.4 percent.","idt":"Harga naik 4 persen. Tabunganmu naik 0,4 persen.","eff":"Rp -600,000","e":{"money":-600000},"flavor":"Savings are a slow leak with a nice logo."},{"id":"K02","deck":"finance","titleEn":"Gadget Installment","titleId":"Cicilan Gadget","en":"Your new phone is paid off in twenty-four installments. It is already old.","idt":"HP barumu lunas dalam dua puluh empat kali cicilan. HP-nya sudah ketinggalan zaman.","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"Depreciation is paid monthly."},{"id":"K03","deck":"finance","titleEn":"Paylater Token","titleId":"Token Paylater","en":"You buy now and pay later. You receive Rp 1,000,000 now, and a Paylater token is added to your card.","idt":"Kamu beli sekarang, bayar nanti. Kamu terima Rp 1.000.000 sekarang, dan token Paylater ditambahkan ke kartumu.","eff":"Rp +1,000,000","e":{"money":1000000},"flavor":"Later is a date that never arrives until it does.","paylater":1000000},{"id":"K04","deck":"finance","titleEn":"Viral Stock","titleId":"Saham Viral","en":"A stock is trending on social media. You buy Rp 2,000,000 of it, because everyone is.","idt":"Sebuah saham trending di medsos. Kamu beli Rp 2.000.000, karena semua orang beli.","eff":"Rp -2,000,000","e":{"money":-2000000},"flavor":"Trending is not a financial term, but it has an effect."},{"id":"K05","deck":"finance","titleEn":"Guru Course","titleId":"Kursus Guru Cuan","en":"The guru promised thirty percent a month. You pay Rp 1,000,000 for the course.","idt":"Gurunya janji untung tiga puluh persen sebulan. Kamu bayar Rp 1.000.000 untuk kursusnya.","eff":"Rp -1,000,000","e":{"money":-1000000},"flavor":"The course is the only guaranteed return."},{"id":"K06","deck":"finance","titleEn":"Lottery Fee","titleId":"Biaya Undian","en":"You won a lottery you never entered. You pay a Rp 500,000 \"tax\" to claim it.","idt":"Kamu menang undian yang tidak pernah kamu ikuti. Kamu bayar pajak Rp 500.000 untuk klaimnya.","eff":"Rp -500,000","e":{"money":-500000},"flavor":"The only lottery where you pay to win."},{"id":"K07","deck":"finance","titleEn":"Rent Renewal","titleId":"Perpanjangan Sewa","en":"Your rent rose 20 percent. The landlord says, \"It's the market.\"","idt":"Sewamu naik 20 persen. Pemilik kos bilang, \"Ini pasar.\"","eff":"Rp -1,000,000","e":{"money":-1000000},"flavor":"The market has a very specific landlord."},{"id":"K08","deck":"finance","titleEn":"Emergency Fund Used","titleId":"Dana Darurat Terpakai","en":"Your emergency fund paid for an emergency.","idt":"Dana daruratmu dipakai untuk keadaan darurat.","eff":"Rp -2,000,000","e":{"money":-2000000},"flavor":"Working as intended, sadly."},{"id":"K09","deck":"finance","titleEn":"Big Discount","titleId":"Diskon Besar","en":"A seventy percent discount on something you did not need.","idt":"Diskon tujuh puluh persen untuk barang yang tidak kamu butuhkan.","eff":"Rp -400,000","e":{"money":-400000},"flavor":"Saving money is spending money on something cheaper."},{"id":"K10","deck":"finance","titleEn":"Compound Interest","titleId":"Bunga Majemuk","en":"Compound interest works for you for once. It is the interest on your credit card.","idt":"Bunga majemuk bekerja untukmu untuk sekali ini. Itu bunga kartu kreditmu.","eff":"Rp -800,000","e":{"money":-800000},"flavor":"Compounding works for whoever is owed."},{"id":"K11","deck":"finance","titleEn":"Zero-Interest Credit","titleId":"Kredit Tanpa Bunga","en":"Zero interest, plus an admin fee, plus insurance, plus everything else.","idt":"Tanpa bunga, ditambah biaya admin, ditambah asuransi, ditambah semua yang lain.","eff":"Rp -300,000","e":{"money":-300000},"flavor":"Zero percent is the interest rate on your attention."},{"id":"K12","deck":"finance","titleEn":"Late Freelance Pay","titleId":"Bayaran Freelance Telat","en":"A client paid sixty days late. You finally get paid.","idt":"Klien bayar telat enam puluh hari. Akhirnya kamu dibayar.","eff":"Rp +1,000,000","e":{"money":1000000},"flavor":"Late payment is the most common freelance benefit."},{"id":"K13","deck":"finance","titleEn":"Crypto Stake","titleId":"Modal Kripto","en":"Your crypto doubled, then halved, then got recommended to your friends.","idt":"Kriptomu naik dua kali, turun setengah, lalu direkomendasikan ke temanmu.","eff":"Kewarasan -2","e":{"kew":-2},"flavor":"The recommendation was the only gain."},{"id":"K14","deck":"finance","titleEn":"Egg Prices","titleId":"Harga Telur","en":"Eggs cost more than last year. You pay Rp 150,000.","idt":"Telur lebih mahal dari tahun lalu. Kamu bayar Rp 150.000.","eff":"Rp -150,000","e":{"money":-150000},"flavor":"The egg is now a status symbol."},{"id":"K15","deck":"finance","titleEn":"Bill Week","titleId":"Minggu Tagihan","en":"Five bills are due this week. You pay Rp 1,200,000.","idt":"Ada lima tagihan minggu ini. Kamu bayar Rp 1.200.000.","eff":"Rp -1,200,000","e":{"money":-1200000},"flavor":"Bills are scheduled like holidays."},{"id":"K16","deck":"finance","titleEn":"Streaming Subscriptions","titleId":"Langganan Streaming","en":"Nine streaming subscriptions, all \"essential.\"","idt":"Sembilan langganan streaming, semuanya \"penting\".","eff":"Rp -450,000","e":{"money":-450000},"flavor":"Essential is the price of entertainment."},{"id":"K17","deck":"finance","titleEn":"Shared Account","titleId":"Rekening Bersama","en":"Your partner asks, \"How much did you spend?\"","idt":"Pasanganmu tanya, \"Tadi habis berapa?\"","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"The shared account is a shared argument."},{"id":"K18","deck":"finance","titleEn":"Friend's Loan","titleId":"Pinjaman Teman","en":"A friend asks to borrow money. You say yes.","idt":"Teman minta pinjam uang. Kamu bilang iya.","eff":"Rp -500,000","e":{"money":-500000},"flavor":"Generosity has a balance and a due date."},{"id":"K19","deck":"finance","titleEn":"Educational Investment","titleId":"Investasi Pendidikan","en":"You invested in yourself. You pay Rp 2,000,000 for the certificate.","idt":"Kamu investasi untuk diri sendiri. Kamu bayar Rp 2.000.000 untuk sertifikatnya.","eff":"Rp -2,000,000","e":{"money":-2000000},"flavor":"The return is a line on your profile."},{"id":"K20","deck":"finance","titleEn":"Financial Freedom","titleId":"Kebebasan Finansial","en":"You reach financial freedom. It turns out to be a free webinar with a paid upsell.","idt":"Kamu mencapai kebebasan finansial. Ternyata webinar gratis dengan upsell berbayar.","eff":"Kewarasan +1","e":{"kew":1},"flavor":"Freedom was the hook. The upsell is the product."},{"id":"M01","deck":"meme","titleEn":"Format: \"This Is Me When\"","titleId":"Format: \"Ini Gue Pas\"","en":"Describe yourself at 3 a.m. with a payment reminder on the screen.","idt":"Gambarkan dirimu jam 3 pagi dengan pengingat bayar di layar.","eff":"Kewarasan +1","e":{"kew":1},"flavor":"Honesty is the cheapest therapy."},{"id":"M02","deck":"meme","titleEn":"Format: Three Stages of Life","titleId":"Format: Tiga Tahap Hidup","en":"Stage 1: wants. Stage 2: needs. Stage 3: reminders.","idt":"Tahap 1: keinginan. Tahap 2: kebutuhan. Tahap 3: pengingat.","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"Stage 3 is where every stage ends."},{"id":"M03","deck":"meme","titleEn":"Format: Expectation vs Reality","titleId":"Format: Harapan vs Kenyataan","en":"Expectation: a bonus. Reality: a reminder to pay.","idt":"Harapan: bonus. Kenyataan: pengingat untuk bayar.","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"The reality has better notifications."},{"id":"M04","deck":"meme","titleEn":"Format: \"Just Invest\"","titleId":"Format: \"Tinggal Investasi\"","en":"Someone says \"just invest.\" You nod while staring at your balance.","idt":"Ada yang bilang \"tinggal investasi\". Kamu mengangguk sambil menatap saldo.","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"Advice is free. The balance is not."},{"id":"M05","deck":"meme","titleEn":"Format: \"Not Me, the Algorithm\"","titleId":"Format: \"Bukan Aku, Algoritmanya\"","en":"Blame the algorithm for a purchase you know you made.","idt":"Salahkan algoritma untuk belanja yang kamu tahu itu ulahmu sendiri.","eff":"Rp -150,000","e":{"money":-150000},"flavor":"Blame is a free feature. Delivery is not."},{"id":"M06","deck":"meme","titleEn":"Format: Cat Reaction","titleId":"Format: Reaksi Kucing","en":"Describe your reaction to a payment as a cat sitting on a keyboard.","idt":"Gambarkan reaksimu saat bayar dengan kucing duduk di atas keyboard.","eff":"Kewarasan +1","e":{"kew":1},"flavor":"Cats have no installments."},{"id":"M07","deck":"meme","titleEn":"Format: Honest Group Chat","titleId":"Format: Jujur di Grup Chat","en":"Your honest message gets three \"haha\" reactions.","idt":"Pesan jujurmu dibalas tiga reaksi \"wkwk\".","eff":"Kewarasan +1","e":{"kew":1},"flavor":"The truth goes down better as a joke."},{"id":"M08","deck":"meme","titleEn":"Format: Three Words","titleId":"Format: Tiga Kata","en":"Describe your bank balance in three words.","idt":"Gambarkan saldo bankmu dalam tiga kata.","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"Three words is the ideal length for a tragedy."},{"id":"M09","deck":"meme","titleEn":"Format: If I Could Choose","titleId":"Format: Kalau Bisa Pilih","en":"Skip your next turn, or lose 1 Kewarasan. You choose.","idt":"Lewati giliran berikutnya, atau kehilangan 1 Kewarasan. Kamu yang pilih.","eff":"Skip 1 turn OR Kewarasan -1","e":{"choice":[{"skip":1},{"kew":-1}]},"flavor":"Every format offers a choice nobody wants."},{"id":"M10","deck":"meme","titleEn":"Format: Rate Your Day","titleId":"Format: Nilai Harimu","en":"Rate today from one to ten. Your score: three.","idt":"Nilai harimu dari satu sampai sepuluh. Nilaimu: tiga.","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"Three is generous."},{"id":"M11","deck":"meme","titleEn":"Format: The Word \"Patience\"","titleId":"Format: Kata \"Sabar\"","en":"Patience is a price tag written nicely.","idt":"Sabar itu label harga yang ditulis rapi.","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"Patience is the most expensive word in the app."},{"id":"M12","deck":"meme","titleEn":"Format: Countdown to Payday","titleId":"Format: Hitung Mundur Gajian","en":"Countdown to payday: 13 days. Your balance: one day.","idt":"Hitung mundur ke gajian: 13 hari. Saldo kamu: satu hari.","eff":"Kewarasan -1","e":{"kew":-1},"flavor":"Payday is always a little further than the calendar says."},{"id":"M13","deck":"meme","titleEn":"Format: Breaking News","titleId":"Format: Breaking News","en":"Breaking: you are fine. Developing: not for long.","idt":"Breaking: kamu baik-baik saja. Developing: tidak lama lagi.","eff":"Kewarasan +1","e":{"kew":1},"flavor":"Breaking news comes every minute. So does the good news."},{"id":"M14","deck":"meme","titleEn":"Format: Survival Tutorial","titleId":"Format: Tutorial Bertahan","en":"Step 1: breathe. Step 2: close the app. Step 3: repeat.","idt":"Langkah 1: tarik napas. Langkah 2: tutup aplikasinya. Langkah 3: ulangi.","eff":"Kewarasan +1","e":{"kew":1},"flavor":"The tutorial has no end screen."},{"id":"M15","deck":"meme","titleEn":"Format: Which One","titleId":"Format: Pilih yang Mana","en":"Which one do you pick: the rent, or the rice? Pay Rp 300,000 to pick both.","idt":"Pilih mana: sewa atau beras? Bayar Rp 300.000 untuk pilih keduanya.","eff":"Rp -300,000","e":{"money":-300000},"flavor":"Choosing both is the only budget strategy."}];
